<script setup>
import {reactive,ref} from 'vue'
import data from '../survey.json'
import {t} from '../i18n'
const answers=reactive(data.questions.map(q=>q.multiple?[]:'')),errors=ref([]),done=ref(false)
function submit(){errors.value=data.questions.map((q,i)=>answers[i].length?null:i).filter(i=>i!==null);if(errors.value.length){document.getElementById('question-'+errors.value[0])?.focus();return}done.value=true}
</script>
<template><section class="survey"><h2>{{data.title}}</h2><p class="survey-intro">{{data.description}}</p><p v-if="done" class="form-success" role="status">{{t('survey.success.submitted')}}</p><form @submit.prevent="submit"><fieldset v-for="(q,i) in data.questions" :key="i" :id="'question-'+i" tabindex="-1" :disabled="done" :aria-describedby="errors.includes(i)?'question-error-'+i:undefined"><legend>{{i+1}}. {{q.title}}<span class="negative"> *</span><small>{{t('survey.hint.'+(q.multiple?'multipleChoice':'singleChoice'))}}</small></legend><label v-for="(option,n) in q.options" :class="{selected:q.multiple?answers[i].includes(option):answers[i]===option}"><input v-model="answers[i]" :type="q.multiple?'checkbox':'radio'" :name="'question-'+i" :value="option"/>{{option}}</label><p v-if="errors.includes(i)" :id="'question-error-'+i" class="form-error">{{t('survey.validation.required')}}</p></fieldset><button v-if="!done" class="primary-button wide-button">{{t('survey.actions.submit')}}</button><p v-else class="positive">{{t('survey.readonly.title')}}</p></form></section></template>
<style scoped>.survey h2{font-size:1.5rem;margin:24px 0 16px}.survey-intro{line-height:1.7;color:#fff9;margin-bottom:32px}.survey fieldset{border:0;padding:0;margin:0 0 32px}.survey legend{font-size:1rem;margin-bottom:16px;line-height:1.6}.survey legend small{margin-left:8px;color:#fff6;font-size:0.75rem}.survey label{display:flex;align-items:center;gap:12px;border:1px solid #ffffff12;border-radius:var(--nt-radius-control);padding:12px 16px;min-height:48px;margin:8px 0;font-size:0.875rem;cursor:pointer}.survey label.selected{border-color:var(--nt-accent);background:#bbff0010}.survey input{width:16px;min-height:16px;height:16px;flex:none;accent-color:var(--nt-accent)}.survey fieldset:focus{outline:2px solid var(--nt-accent);outline-offset:8px}.survey fieldset:disabled{opacity:.8}</style>
